package com.northstar.cart;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;import java.util.concurrent.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/carts") @CrossOrigin(origins="${FRONTEND_URL:http://localhost:5173}") public class CartController{private final Map<String,Map<String,Integer>>carts=new ConcurrentHashMap<>();public record Item(@NotBlank String productId,@Min(1)@Max(99)int quantity){}public record Quantity(@Min(1)@Max(99)int quantity){}public record Cart(List<Item>items){}@GetMapping("/{u}")public Cart get(@PathVariable String u){return view(u);}@PostMapping("/{u}/items")public Cart add(@PathVariable String u,@Valid@RequestBody Item i){carts.computeIfAbsent(u,k->new ConcurrentHashMap<>()).merge(i.productId(),i.quantity(),(a,b)->Math.min(99,a+b));return view(u);}@PutMapping("/{u}/items/{id}")public Cart update(@PathVariable String u,@PathVariable String id,@Valid@RequestBody Quantity q){carts.computeIfAbsent(u,k->new ConcurrentHashMap<>()).put(id,q.quantity());return view(u);}@DeleteMapping("/{u}/items/{id}")public Cart remove(@PathVariable String u,@PathVariable String id){carts.computeIfAbsent(u,k->new ConcurrentHashMap<>()).remove(id);return view(u);}@DeleteMapping("/{u}")public Cart clear(@PathVariable String u){carts.remove(u);return view(u);}private Cart view(String u){return new Cart(carts.getOrDefault(u,Map.of()).entrySet().stream().map(e->new Item(e.getKey(),e.getValue())).toList());}}
